<parameter=command>cd /workspace/repo-vul/src-vul && sed -n '150,180p' drivers/driver_geostar.c && echo "=====" && grep -n "geostar_parse_packet\|geostar_dispatch\|static gps_mask_t" drivers/driver_geostar.c | head -20</｜｜DSML｜｜>
</｜｜DSML｜｜>

